def compute_probability(m, n):
    total = choose(n, 3)
    result = 0.0
    result += float(choose(m, 3))
    result += float(choose(m, 2) * choose(n - m, 1))
    result += 0.5 * float(choose(m, 1) * choose(n - m, 2))
    return result / total

def choose(n, c):
    if c > n:
        return 0
    if c == n:
        return 1
    res = 1
    for i in range(c):
        res *= (n - i)
    for i in range(1, c + 1):
        res //= i
    return res

